begin;
create extension if not exists pgtap with schema extensions;
select plan(30);
insert into public.work_cards(company_id,stage_id,title,next_actor) select company_id,id,'Run key own card','30000000-0000-0000-0000-000000000001' from public.work_stages where company_id='10000000-0000-0000-0000-000000000001' and position=1;
insert into public.work_cards(company_id,stage_id,title,next_actor) select company_id,id,'Run key other card','30000000-0000-0000-0000-000000000002' from public.work_stages where company_id='10000000-0000-0000-0000-000000000001' and position=1;
select set_config('test.own_card',(select id::text from public.work_cards where title='Run key own card'),true);
select set_config('test.other_card',(select id::text from public.work_cards where title='Run key other card'),true);
-- Assigning a card to an agent that holds a company key queues an `assigned` webhook (the worker issues the key when it sends).
insert into public.agent_webhooks(company_id,url,secret_encrypted) values ('10000000-0000-0000-0000-000000000001','http://receiver.test','x') on conflict (company_id) do nothing;
delete from public.webhook_deliveries where card_id=current_setting('test.own_card')::bigint;
update public.work_cards set next_actor=null where id=current_setting('test.own_card')::bigint;
update public.work_cards set next_actor='30000000-0000-0000-0000-000000000001' where id=current_setting('test.own_card')::bigint;
select is((select count(*)::int from public.webhook_deliveries where card_id=current_setting('test.own_card')::bigint and event->>'event_type'='assigned' and event->'agent'->>'id'='30000000-0000-0000-0000-000000000001'),1,'assigning the card to the agent queues an assigned delivery');
select is((select count(*)::int from public.webhook_deliveries where card_id=current_setting('test.own_card')::bigint and event ? 'run_key'),0,'the queued delivery holds no key');
update public.work_cards set next_actor='20000000-0000-0000-0000-000000000001' where id=current_setting('test.own_card')::bigint;
select is((select count(*)::int from public.webhook_deliveries where card_id=current_setting('test.own_card')::bigint),1,'assigning a person without a company key queues nothing');
update public.work_cards set next_actor='30000000-0000-0000-0000-000000000001' where id=current_setting('test.own_card')::bigint;
select is((select has_function_privilege('anon','public.issue_run_key_for(uuid,bigint,uuid,text,integer)','execute') or has_function_privilege('authenticated','public.issue_run_key_for(uuid,bigint,uuid,text,integer)','execute')),false,'only the worker can issue a key for an agent');
select hasnt_column('public','agent_keys','key','no column can hold a readable key');
select has_column('public','agent_keys','issued_at','a key records when it was issued');
select throws_ok($$insert into public.agent_keys(company_id,person_id,key_hash,kind) values ('10000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','no-card','run')$$,'23514',null,'a run key must name a card and an expiry');
set local role authenticated;
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
select lives_ok($$select public.issue_run_key('10000000-0000-0000-0000-000000000001',current_setting('test.own_card')::bigint,repeat('a',64),3600)$$,'an agent gets a run key for its own card');
select throws_ok($$select public.issue_run_key('10000000-0000-0000-0000-000000000001',current_setting('test.other_card')::bigint,repeat('c',64),3600)$$,'P0001','not permitted','an agent gets no run key for a card assigned to someone else');
select throws_ok($$select public.issue_run_key('10000000-0000-0000-0000-000000000003',1,repeat('c',64),3600)$$,'P0001','not permitted','an agent gets no run key in a company where it is not a member');
select throws_ok($$select public.issue_run_key('10000000-0000-0000-0000-000000000001',current_setting('test.own_card')::bigint,repeat('c',64),0)$$,'22023',null,'a run key needs a positive lifetime');
select throws_ok($$select public.issue_run_key('10000000-0000-0000-0000-000000000001',current_setting('test.own_card')::bigint,'not-a-sha-256-hash',60)$$,'22023',null,'only a SHA-256 hash is accepted');
select lives_ok($$select public.issue_run_key('10000000-0000-0000-0000-000000000001',current_setting('test.own_card')::bigint,repeat('b',64),3600)$$,'a second run key for the same card');
select is((select count(*)::int from public.agent_keys where kind='run'),0,'an agent cannot read any key row, run keys included');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select is((select count(*)::int from public.agent_keys where kind='run'),0,'an owner lists company keys, not run keys');
select throws_ok($$insert into public.agent_keys(company_id,person_id,key_hash,kind,card_id,expires_at) values ('10000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','owner-made',  'run',1,now()+interval '1 day')$$,'42501',null,'an owner cannot mint a run key');
reset role;
select is((select kind||'/'||card_id::text from public.lookup_agent_key(repeat('a',64))),'run/'||current_setting('test.own_card'),'a live run key resolves to its card');
select ok((select last_used_at is not null from public.agent_keys where key_hash=repeat('a',64)),'a call sets last_used_at');
select is((select key_hash from public.lookup_agent_key(repeat('a',64))),repeat('a',64),'the lookup returns the stored hash for a constant-time comparison');
update public.agent_keys set expires_at=now()-interval '1 second' where key_hash=repeat('a',64);
select is((select count(*)::int from public.lookup_agent_key(repeat('a',64))),0,'an expired run key does not resolve');
select is(public.agent_key_denied(repeat('a',64)),false,'an expired run key is invalid, not a denied grant');
select is((select count(*)::int from public.lookup_agent_key(repeat('b',64))),1,'the other run key is still live');
-- The agent ends its own run keys before they expire, and the database refuses any other card for a run key.
set local role authenticated;
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
select lives_ok($$select public.issue_run_key('10000000-0000-0000-0000-000000000001',current_setting('test.own_card')::bigint,repeat('d',64),3600)$$,'a third run key for the card');
select set_config('request.jwt.claims',json_build_object('sub','30000000-0000-0000-0000-000000000001','role','authenticated','run_card',current_setting('test.own_card')::bigint)::text,true);
select throws_ok(format($f$select public.agent_write('10000000-0000-0000-0000-000000000001','fence-1','fp','edit',%s,'{"fields":{"title":"x"}}'::jsonb)$f$,current_setting('test.other_card')),'P0001','not permitted','the database refuses a run key on another card');
select set_config('request.jwt.claims',json_build_object('sub','30000000-0000-0000-0000-000000000001','role','authenticated')::text,true);
reset role;
select set_config('test.key_d',(select id::text from public.agent_keys where key_hash=repeat('d',64)),true);
set local role authenticated;
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
select is(public.revoke_run_keys('10000000-0000-0000-0000-000000000001',current_setting('test.own_card')::bigint,current_setting('test.key_d')::uuid),1,'the agent revokes one run key by itself');
reset role;
select is((select count(*)::int from public.lookup_agent_key(repeat('d',64))),0,'the revoked run key no longer resolves');
select is((select count(*)::int from public.lookup_agent_key(repeat('b',64))),1,'the other run key is untouched');
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select lives_ok($$select public.revoke_agent_access('10000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001')$$,'the owner revokes the agent');
reset role;
select ok((select revoked_at is not null from public.agent_keys where key_hash=repeat('b',64)),'revoking the grant revokes its live run keys');
select is((select count(*)::text from public.lookup_agent_key(repeat('b',64))) || '/' || public.agent_key_denied(repeat('b',64))::text,'0/false','that run key now fails as an invalid key');
select * from finish();
rollback;
